svg.script:
/*
 * Creates a new about:blank tab and puts
 * the requested website inside an iframe.
 */
function openEmbedded(url) {

  var tab = window.open("", "_blank");

  if (!tab) {
    alert(
      "The browser blocked the popup.\n\n" +
      "Allow popups for this page and try again."
    );
    return;
  }

  var html =
    '<!DOCTYPE html>' +
    '<html>' +
    '<head>' +
    '<meta charset="UTF-8">' +
    '<meta name="viewport" content="width=device-width, initial-scale=1.0">' +
    '<title>Embedded</title>' +

    '<style>' +
    '* {' +
      'box-sizing:border-box;' +
    '}' +

    'html, body {' +
      'margin:0;' +
      'padding:0;' +
      'width:100%;' +
      'height:100%;' +
      'overflow:hidden;' +
      'background:#000;' +
    '}' +

    'iframe {' +
      'display:block;' +
      'width:100%;' +
      'height:100%;' +
      'border:0;' +
      'margin:0;' +
      'padding:0;' +
    '}' +
    '</style>' +

    '</head>' +
    '<body>' +

    '<iframe ' +
      'src="' + escapeAttribute(url) + '"' +
      'allowfullscreen>' +
    '</iframe>' +

    '</body>' +
    '</html>';

  try {
    tab.document.open();
    tab.document.write(html);
    tab.document.close();
  } catch (error) {
    tab.location.href = url;
  }
}


/*
 * Safely escape a URL before putting it
 * inside an HTML attribute.
 */
function escapeAttribute(value) {
  return String(value)
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}


/*
 * Attach button events.
 */
function setupButtons() {

  var lucide = document.getElementById("lucideButton");
  var fern = document.getElementById("fernButton");

  if (!lucide || !fern) {
    return;
  }


  lucide.addEventListener("click", function () {

    openEmbedded(
      "https://cdn.jsdelivr.net/gh/lucideproxy/svg@latest/logo.svg"
    );

  });


  fern.addEventListener("click", function () {

    openEmbedded(
      "https://s3.amazonaws.com/mathvc/index.html"
    );

  });

}


/*
 * foreignObject content can be created after
 * the SVG script runs, so wait for the SVG
 * document to finish loading.
 */
window.addEventListener("load", function () {
  setupButtons();
});
